<?php require_once __DIR__.'/../../includes/functions.php';$u=require_auth();$d=request_json();verify_csrf($d['_csrf']??'');$parent=(int)($d['parent_id']??root_folder_id($u['id']));$name=trim($d['name']??'New Folder');if($name==='')json_response(['error'=>'Folder name required.'],422);$st=db()->prepare('SELECT id FROM folders WHERE id=? AND user_id=?');$st->execute([$parent,$u['id']]);if(!$st->fetch())json_response(['error'=>'Parent not found.'],404);$ins=db()->prepare('INSERT INTO folders(user_id,parent_id,folder_name) VALUES(?,?,?)');$ins->execute([$u['id'],$parent,$name]);log_activity($u['id'],'Create folder',null,$parent,'Created folder '.$name);json_response(['ok'=>1,'id'=>(int)db()->lastInsertId()]);